effect.shader:
void main(){
    vec2 px=(1.0+size*4.0)/acScreenSize;
    vec4 src=texture2DCv(inputImg.texture, acScreenNorm);
    float al=texture2DCv(inputImg.texture, acScreenNorm-vec2(px.x,0.0)).a;
    float ar=texture2DCv(inputImg.texture, acScreenNorm+vec2(px.x,0.0)).a;
    float au=texture2DCv(inputImg.texture, acScreenNorm-vec2(0.0,px.y)).a;
    float ad=texture2DCv(inputImg.texture, acScreenNorm+vec2(0.0,px.y)).a;
    vec3 nrm=normalize(vec3((al-ar)*4.0,(au-ad)*4.0,1.0));
    float a=radians(lightAngle);
    vec3 L=normalize(vec3(cos(a),sin(a),0.6));
    float d=dot(nrm,L);
    float lit=1.0+ d*strength;
    gl_FragColor=vec4(clamp(src.rgb*lit,0.0,1.0), src.a);
}
